#!/usr/bin/env python3
"""Verify a full exact integral matrix certificate generated by v0.6 standalone ZIP.

Usage: python3 verify_integral_bridge_v06.py /path/to/integral_bridge_matrices_v06.json
Requires SymPy and prior v0.4/v0.5 experiment scripts in the same folder.
This verifies mathematical matrix equations; not a physical bridge.
"""
from pathlib import Path
import runpy, contextlib, io, json, sys
import sympy as S
root=Path(__file__).resolve().parent
if len(sys.argv)!=2:raise SystemExit("Pass exact matrix JSON file exported by v0.6.")
with contextlib.redirect_stdout(io.StringIO()):
 src=runpy.run_path(str(root/"twisted_72_boundary_v05.py"))
 dst=runpy.run_path(str(root/"bulk_bridge_v04.py"))
B=src["boundary"];d=dst["dS"];f=dst["dT"];M=dst["M"]
obj=json.loads(Path(sys.argv[1]).read_text())
def matrices(key):
 out=[]
 for block in obj[key]:
  z=S.zeros(*block["shape"])
  for i,j,v in block["entries"]:
   assert isinstance(v,int)
   z[i,j]=v
  out.append(z)
 return out
P,T,H,C=[matrices(k) for k in ("P","S","H","to60")]
assert [list(a.shape) for a in P]==[[2,18],[5,102],[4,156],[1,72]]
for k in range(4):
 assert P[k]*T[k]==S.eye(P[k].rows)
 if k<3:
  a=B[k+1]*H[k]
 else:a=S.zeros(T[k].rows)
 if k:a+=H[k-1]*B[k]
 assert a==S.eye(T[k].rows)-T[k]*P[k]
for k in (1,2,3):
 assert d[k-1]*P[k]==P[k-1]*B[k]
 assert B[k]*T[k]==T[k-1]*d[k-1]
 assert f[k-1]*C[k]==C[k-1]*B[k]
 assert C[k]==M[k]*P[k]
print(json.dumps({"status":"PASS_EXACT","integral_chain_homotopy":True,
 "twisted_H0_Z2_preserved":True,"full_chain_map_into_60D":True,
 "physical_promotion":0},indent=2))
